import { ATTRACTION_IMAGES } from "./attraction-images";
import { ACTIVITY_IMAGES } from "./activity-images";

export interface Activity {
  name: string;
  image: string;
}

export interface Attraction {
  id: string;
  name: string;
  city: string;
  country: string;
  description: string;
  image: string;
  rating: number;
  /** Approximate per-person visit cost range, in USD. */
  budgetMin: number;
  budgetMax: number;
  bestTime: string;
  /** Three to five must-see activities at this destination. */
  activities: Activity[];
  funFact: string;
}

/** Formats a budget range the way it should read on a card badge, e.g. "$150-250". */
export function formatBudget(min: number, max: number): string {
  return `$${min}-${max}`;
}

export type CountryCode =
  | "AR" | "AT" | "AU" | "BE" | "BR" | "CA" | "CH" | "CL" | "CN" | "CO"
  | "CR" | "CZ" | "DE" | "EG" | "ES" | "FI" | "FR" | "GB" | "GR" | "HR"
  | "HU" | "ID" | "IE" | "IN" | "IS" | "IT" | "JP" | "KE" | "KR" | "MA"
  | "MX" | "MY" | "NL" | "NO" | "NP" | "NZ" | "PE" | "PH" | "PL" | "PT"
  | "RU" | "SE" | "SG" | "TH" | "TR" | "TZ" | "AE" | "US" | "VN" | "ZA";

